 // Turm-Bosse: Name, Angriffe, Beschreibung; n2/m2 = Name und Angriffe der 2. Phase
 tboss:[
  {n:"Torwächter Eisenbart",mv:["Hellebardenstoß","Torbrecher","Deckung"],d:"Bewacht seit hundert Jahren das Turmtor. Holt er weit aus, geh in Deckung!"},
  {n:"Kerkermeister Grimmbold",mv:["Kettenhieb","Fußfessel","Schlüsselbund"],d:"Lässt seine Kettenhunde los. Erst die Hunde, dann der Meister."},
  {n:"Kristallgolem",mv:["Kristallfaust","Splitterschlag","Prismenstoß","Kristallhaut"],d:"Gift perlt an ihm ab. Sein Spiegelschild wirft deine Hiebe zurück."},
  {n:"Magmawurm Glutschlund",mv:["Glutbiss","Lavaspeien","Schwanzpeitsche"],d:"Feuer kann ihm nichts anhaben. Halb besiegt, taucht er in die Lava und kehrt glühend zurück.",n2:"Glühender Glutschlund",m2:["Glutbiss","Magmaflut","Ausbruch"]},
  {n:"Die Graue Witwe",mv:["Klagekralle","Totenhauch","Seelengriff"],d:"Saugt dir das Leben aus, und ihr Fluch versiegelt deine Künste."},
  {n:"Sturmharpyie Kreischkralle",mv:["Krallenhieb","Donnerschrei","Sturzflug"],d:"Schwer zu treffen. Kreist sie hoch oben, folgt der Blitzsturz."},
  {n:"Dein Schattenzwilling",mv:["Schattenhieb","Spiegelschlag","Schattendeckung"],d:"Er kämpft wie du und trägt, was du trägst. Hebt er den Spiegel, halte inne."},
  {n:"Rissbewahrer Xal'Zorr",mv:["Leerenhieb","Rissfeuer","Weltenschnitt"],d:"Ruft Leerenschwärmer aus dem Riss, zweimal, wenn du ihn nicht schnell bezwingst."},
  {n:"Uhrwerk-Koloss",mv:["Zahnradhieb","Federschlag","Panzerplatten"],d:"Tickt, zieht sich auf und schlägt zu. Seine polierten Platten spiegeln."},
  {n:"Der Gesichtslose Bibliothekar",mv:["Buchschlag","Brennende Seite","Bannwort"],d:"Fliegende Bücher schützen ihn, und seine Bannworte versiegeln deine Künste."},
  {n:"Sporenmutter",mv:["Rankenhieb","Sporenwolke","Wurzelschlag"],d:"Gebiert Sporlinge und vergiftet die Luft."},
  {n:"Frostwyrm Gletscherzahn",mv:["Eisbiss","Frostodem","Schwanzhieb"],d:"Holt tief Luft für seinen Eisatem. Halb besiegt, bricht er aus seinem Panzer.",n2:"Entfesselter Gletscherzahn",m2:["Eissturm","Gletscherbruch","Frostbiss"]},
  {n:"Blutrosen-Gräfin",mv:["Dornenpeitsche","Rosengift","Blutkuss"],d:"Trinkt dein Blut, und ihr Dornenpanzer sticht zurück."},
  {n:"Knochenkönig Ossarion",mv:["Knochenkeule","Grabeskälte","Schädelspalter","Knochenwall"],d:"Ruft seine Skelette und steht einmal wieder auf, wenn du ihn fällst."},
  {n:"Schmiedetitan Ambossar",mv:["Hammerschlag","Glutfunken","Ambosswall"],d:"Feuerfest. Er holt mit dem Hammer aus, und halb besiegt glüht seine Rüstung auf.",n2:"Glühender Ambossar",m2:["Glühhammer","Schmiedebeben","Funkenregen"]},
  {n:"Die Spiegelkönigin",mv:["Scherbenhieb","Blendlicht","Spiegelstich"],d:"Schwer zu treffen. Ihre Spiegel werfen Schaden zurück, ihr Blick versiegelt deine Künste."},
  {n:"Albtraumweber",mv:["Traumfaden","Albdruck","Schlafgift"],d:"Versiegelt deine Künste. Halb besiegt zeigt er sein wahres Gesicht.",n2:"Erwachter Albtraum",m2:["Albtraumgift","Schreckensnetz","Wahnsinn"]},
  {n:"Sternenseher Astralon",mv:["Sternenstab","Sternenfeuer","Himmelsschlag"],d:"Ruft Sternsplitter herbei und lässt Meteore fallen."},
  {n:"Urdrache Aurelion",mv:["Goldkralle","Drachenfeuer","Schwanzschlag"],d:"Feuerfest. Er holt tief Luft, und halb besiegt erhebt er sich in die Lüfte.",n2:"Aurelion im Zorn",m2:["Feuersturm","Himmelssturz","Goldener Odem"]},
  {n:"Der Turmherr",mv:["Kronenschlag","Bannblick","Turmfeuer","Urteil"],d:"Herr über alle Etagen. Ruft seine Garde, verwandelt sich und kehrt einmal aus dem Tod zurück.",n2:"Der Turmherr entfesselt",m2:["Sternenbrand","Seelengift","Letztes Urteil"]}],
