 // Rivale Sir Gregor: Dialog vor dem Duell, nach Sieg, nach Niederlage
 rival:[
  {pre:"„So, so – ein neuer Knappe, der sich Ritter nennt? Ich bin Sir Gregor. Merk dir den Namen, denn du wirst ihn noch oft im Staub hören!“",win:"„Glück! Pures Glück! Das nächste Mal …“ Gregor stapft wütend davon.",lose:"„Ha! Wie ich dachte. Komm wieder, wenn du ein Schwert halten kannst.“"},
  {pre:"„Man erzählt sich Geschichten über dich im Königreich. Lächerlich! Ich werde allen zeigen, wer der wahre Held ist.“",win:"„Das … das ist unmöglich! Ich habe Tag und Nacht trainiert!“",lose:"„Siehst du? Die Geschichten waren erfunden.“"},
  {pre:"„Ich habe mir ein verzaubertes Schwert besorgt. Diesmal gibt es keine Ausreden – für keinen von uns.“",win:"Gregor lässt das Schwert sinken. „Du kämpfst … mit Ehre. Das ärgert mich am meisten.“",lose:"„Endlich! Endlich erkennt jeder, wer der Bessere ist!“"},
  {pre:"„Der König hat dich zum Turnierchampion ernannt. Mich hat er nicht einmal angesehen. Zieh dein Schwert!“",win:"„Vielleicht … vielleicht habe ich das falsche Ziel verfolgt.“ Gregor wirkt nachdenklich.",lose:"„Das war für jeden Tag, an dem man mich übersehen hat!“"},
  {pre:"„Ich habe gegen die Eiskönigin gekämpft – und verloren. Du hast sie besiegt. Zeig mir, wie viel Abstand zwischen uns liegt.“",win:"„Ein großer Abstand.“ Zum ersten Mal lächelt Gregor. „Aber ich hole auf.“",lose:"„Heute nicht so weit, wie du dachtest, was?“"},
  {pre:"„Die Dunkelheit wächst. Bevor wir beide in den letzten Kampf ziehen, will ich es ein letztes Mal wissen – als Rivalen.“",win:"„Ich war ein Narr, dich zu beneiden. Das Königreich braucht dich.“",lose:"„Ein letzter Sieg für den alten Gregor. Danke dir dafür.“"},
  {pre:"„Kein Neid mehr, kein Groll. Nur ein letztes Duell unter Freunden. Gib alles!“",win:"Gregor reicht dir sein Schwert. „Die <b>Neidklinge</b> – nimm sie. Sie hat einen würdigeren Träger verdient. Es war mir eine Ehre, dein Rivale zu sein.“",lose:"„Noch nicht ganz, mein Freund. Ich warte auf dich!“"}],
 // Boss-Geschichten: [vor dem Kampf, nach dem Sieg]
 lore:[
  ["Graukopf war einst Hauptmann der Stadtwache – bis er die Steuern des Königs stahl und in die Wälder floh.","„Nimm mein Gold … es hat mir ohnehin nur Unglück gebracht.“"],
  ["Niemand hat je das Gesicht des Schwarzen Ritters gesehen. Man sagt, unter dem Helm sei nur Schatten.","Der Helm fällt – und darunter ist … nichts. Nur ein kalter Hauch, der verweht."],
  ["Vulkanus erwachte, als die Minen zu tief gegraben wurden. Seitdem brennen die Dörfer am Feuerberg.","Der Drache sinkt nieder. Die Glut in seinen Augen erlischt, und der Berg wird still."],
  ["Frostara herrschte einst gütig über den Norden – bis ein Fluch ihr Herz zu Eis erstarren ließ.","„Danke …“, haucht sie, als das Eis um ihr Herz bricht. Dann zerfällt sie zu Schneeflocken."],
  ["Mortrax war der Hofmagier des alten Königs. Für die Unsterblichkeit opferte er alles – auch seine Seele.","Der Lich zerfällt zu Staub. Seine Krone rollt klirrend über den Boden."],
  ["Azgaroth wurde durch die Gier der Menschen aus der Unterwelt gerufen. Mit jedem Krieg wird er stärker.","Mit einem letzten Brüllen wird der Dämon in die Tiefe zurückgezogen. Die Erde schließt sich."],
  ["Donnerfaust schlief tausend Jahre in den Wolken. Azgaroths Sturz hat ihn geweckt – und er ist zornig.","Der Riese lacht donnernd. „Endlich ein würdiger Gegner!“ Dann löst er sich in Regen auf."],
  ["Morgana stahl Frostaras Fluch und machte ihn zu ihrer Waffe. Sie will die Herrschaft über alle Königreiche.","Morganas Hut fällt zu Boden. Ihre Flüche verlieren ihre Macht, und die Wälder atmen auf."],
  ["Abyssor erhob sich aus der Tiefsee, als Morgana fiel. Seine Tentakel reißen ganze Schiffe in die Tiefe.","Der Krake versinkt in den Wellen. Am Strand finden Fischer seine goldene Krone."],
  ["Ignarion ist so alt wie die Sonne. Er verbrennt die Welt, damit sie aus der Asche neu entstehen kann.","Der Phönix zerfällt zu Asche – und aus ihr steigt ein kleines, friedliches Flämmchen auf."],
  ["Nyx ist die Herrin der ewigen Nacht. Wo sie wandelt, erlöschen die Sterne.","Mit Nyx' Sturz kehren die Sterne an den Himmel zurück, einer nach dem anderen."],
  ["Der Weltenfresser ist der Ursprung aller Bosheit. Alle, die du besiegt hast, waren nur seine Schatten.","Das Auge schließt sich für immer. Die Welt ist gerettet."]],
 // Tipps beim ersten Öffnen
 hints:{
  inv:"Hier siehst du alles, was du trägst, deine Kampfwerte und deinen Beutel mit Zufallsbeute. Du legst Funde an und ab, vergleichst sie und zerlegst, was du nicht brauchst, in Materialien.",
  skills:"Du hast 6 Plätze für Fähigkeiten. Der Schwerthieb ist immer dabei. Tausche Fähigkeiten je nach Gegner aus – vor dem Kampf, nicht währenddessen.",
  craft:"Drei Berufe: <b>Schmied</b> wertet Ausrüstung auf, <b>Alchemie</b> braut Tränke, <b>Verzauberer</b> setzt Runen ein. Jedes Herstellen kostet 1 Energie und Materialien.",
  trader:"Der Händler verkauft alle Materialien und kauft übrige für 40 % zurück. Am Markttag (Samstag) ist alles günstiger.",
  burg:"Gebäude bringen jede Nacht Erträge – aber nur, wenn du am Tag fleißig warst (mindestens 4 Energie für volle Erträge).",
  tavern:"Würfelpoker: Tippe die Würfel an, die du neu werfen willst. Paare und Drillinge behalten, den Rest neu werfen. Höchstens 5 Partien pro Tag.",
  comp:"Begleiter helfen dir passiv. Du kannst mehrere kaufen, aber nur einen mitnehmen – wähle passend zu deinem Ziel.",
  best:"Jeder Gegner, dem du begegnest, landet hier – mit seinen Angriffen. Kennst du die Angriffe, weißt du, welche Tränke du brauchst.",
  save:"Sichere deinen Spielstand regelmäßig mit <b>Exportieren</b> – zum Beispiel als Datei. Damit kannst du ihn auf ein anderes Gerät übertragen oder nach dem Löschen der Browserdaten wiederherstellen."}
